"""Standalone raster QA viewer; shared time, source bones and image diagnostics."""
import gzip,json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[4];STUDY=ROOT/'research/sprite-animation/eight-walk-factory-v20'
data=json.loads(gzip.decompress((STUDY/'evidence/viewer-data.json.gz').read_bytes()));summary=json.loads((STUDY/'evidence/summary.json').read_text())
for b in data:
 r=json.loads((STUDY/'evidence'/(b['facing']+'-motion-report.json')).read_text());b['metrics']=r['surface_axis_metrics'];b['blockers']=r['blockers'];b['flow']=r['flow'];b['status']=r['status']
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eight-direction sprite motion QA</title><style>body{margin:20px;background:#191c22;color:#eee;font:16px system-ui}button,select,input{font:inherit;margin:6px}canvas{width:100%;max-width:320px;display:block;margin:auto;background:#272727}.grid,.detail{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:12px}.card{background:#272727;padding:10px;min-width:0}.card h3{font-size:18px;height:48px;margin:0}.warning{color:#ffd19a}.detail{margin:20px 0}table{border-collapse:collapse}td,th{padding:8px;border:1px solid #555}p{max-width:1100px;line-height:1.5}#plot{max-width:900px;background:#15181c}.small{font-size:14px}label{display:inline-block}</style><h1>เดิน8ทิศ / motion QA</h1><p class="warning">64 painted frames are review drafts. W is preserved: user says animation looks better but still bounces slightly. Source bones are actual original rig; RO pose correspondence is approximate. Hidden painted hips/root/contacts remain unresolved.</p><button id="play">Play</button><button id="prev">Previous</button><button id="next">Next</button><select id="clock"><option value="600">600ms /8×75ms precise review</option><option value="800">800ms /8×100ms uniform control</option></select><select id="facing"></select><input id="phase" type="range" min="0" max="7" value="0"><output id="readout"></output><label><input id="bones" type="checkbox">Original bone guide on selected draft</label><label><input id="surface" type="checkbox" checked>Measured hair-region trajectory</label><div id="grid" class="grid"></div><h2>Selected direction: frame-by-frame</h2><div id="detail" class="detail"></div><p id="metrics"></p><canvas id="plot" width="900" height="220"></canvas><p id="blockers" class="warning small"></p><p>กราฟเป็นแนวดิ่งของพิกเซลผมที่ตรวจได้ ไม่ใช่ root หรือคะแนนความเป็นธรรมชาติ เส้น bone เป็นกระดูกจริงของต้นแบบอีกชุด ไม่ใช่กระดูก RO ที่กู้มาได้ หรือเครื่องยืนยันว่าภาพเจนจับขาถูก จุดตัด/สะโพกที่ถูกบังต้องมีหลักฐานตรวจภาพเพิ่ม</p><p>All canvases use the same authored512×512 frame and fixed scale. No per-frame centering, silhouette fit, freezing or mirroring. Detailed source passes and exact source times are retained. Switching direction preserves phase; it is a review control, not a validated game turning animation.</p><script>const DATA=__DATA__;let playing=false,t=0,last=0,k=0;const cache=new Map();function img(src){if(!cache.has(src)){const im=new Image();im.src=src;im.onload=draw;cache.set(src,im)}return cache.get(src)}const tiles=DATA.map(b=>{const e=document.createElement('div');e.className='card';e.innerHTML='<h3>'+b.facing+' · '+b.status+'</h3><canvas width="512" height="512"></canvas><output></output>';grid.append(e);facing.add(new Option(b.facing,b.facing));return e});facing.value='W';const labels=['RO captured raster','Original dressed owner guide','Original cutaway owner guide','Our painted draft'];const panels=labels.map(label=>{const e=document.createElement('div');e.className='card';e.innerHTML='<h3>'+label+'</h3><canvas width="512" height="512"></canvas>';detail.append(e);return e});function boneLines(ctx,b){ctx.lineWidth=2;for(const side of ['r','l']){ctx.strokeStyle=side==='r'?'#3591ff':'#ff922d';const ns=['thigh','calf','foot','ball_leaf'].map(n=>n+'_'+side);ctx.beginPath();ns.forEach((n,i)=>{const p=b[n].xy;i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.stroke();for(const n of ns){ctx.beginPath();ctx.arc(...b[n].xy,4,0,Math.PI*2);ctx.stroke()}}}function paint(canvas,src,type,b){const c=canvas.getContext('2d');c.clearRect(0,0,512,512);const im=img(src);if(im.complete&&im.naturalWidth){c.imageSmoothingEnabled=type!=='RO';if(type==='RO')c.drawImage(im,(512-im.naturalWidth*3)/2,110,im.naturalWidth*3,im.naturalHeight*3);else c.drawImage(im,0,0,512,512)}if(type==='bone'||(type==='art'&&bones.checked))boneLines(c,b.bones[k]);if(type==='art'&&surface.checked&&b.metrics){const pts=b.metrics.xy;c.strokeStyle='#e9ee5d';c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.lineTo(...pts[0]);c.stroke();c.fillStyle='#e9ee5d';c.beginPath();c.arc(...pts[k],4,0,Math.PI*2);c.fill()}}function draw(){k=Math.floor((t%Number(clock.value))/(Number(clock.value)/8));phase.value=k;DATA.forEach((b,i)=>{paint(tiles[i].querySelector('canvas'),b.art[k],'none',b);tiles[i].querySelector('output').textContent='frame '+(k+1);tiles[i].dataset.frame=k});const b=DATA.find(b=>b.facing===facing.value);paint(panels[0].querySelector('canvas'),b.RO[k],'RO',b);paint(panels[1].querySelector('canvas'),b.owner[k],'bone',b);paint(panels[2].querySelector('canvas'),b.cutaway[k],'bone',b);paint(panels[3].querySelector('canvas'),b.art[k],'art',b);metrics.textContent=b.metrics?'Hair-region vertical step max '+b.metrics.max_vertical_step_px.toFixed(2)+'px · vertical range '+b.metrics.vertical_range_px.toFixed(2)+'px · flow '+b.flow.status:'Surface measurement inconclusive';blockers.textContent=b.blockers.join(' · ');readout.textContent=b.facing+' / frame '+(k+1)+' / '+clock.value+'ms';const c=plot.getContext('2d');c.clearRect(0,0,900,220);if(b.metrics){const pts=b.metrics.xy;const lo=Math.min(...pts.map(p=>p[1]))-5,hi=Math.max(...pts.map(p=>p[1]))+5;c.strokeStyle='#e9ee5d';c.lineWidth=2;c.beginPath();pts.concat([pts[0]]).forEach((p,i)=>{const x=30+i*100,y=25+(p[1]-lo)/(hi-lo)*165;i?c.lineTo(x,y):c.moveTo(x,y);c.fillStyle='#eee';c.fillText(String(i%8+1),x,212)});c.stroke();c.fillText('image y downward; final point repeats frame1 to expose seam',30,15)}}function scrub(n){playing=false;play.textContent='Play';t=(n+8)%8*Number(clock.value)/8;draw()}prev.onclick=()=>scrub(k-1);next.onclick=()=>scrub(k+1);phase.oninput=()=>scrub(Number(phase.value));facing.onchange=draw;bones.onchange=draw;surface.onchange=draw;clock.onchange=()=>{t=k*Number(clock.value)/8;draw()};play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play';last=0};function tick(now){if(playing&&last)t+=Math.min(now-last,100);last=now;if(playing)draw();requestAnimationFrame(tick)}window.QA={DATA,get frame(){return k},get playing(){return playing},setTime:v=>{t=v;draw()},draw};draw();requestAnimationFrame(tick);</script>'''
(STUDY/'motion-review.html').write_text(html.replace('__DATA__',json.dumps(data)))
print('Standalone raster motion viewer built:8facing phase controls, bones and actual pixel metrics')
